const NinePatchAsset *findNinePatchAsset(const std::string &pathOrName) {
    if (pathOrName.empty()) return nullptr;
    std::string key = pathOrName;
    const size_t slash = key.find_last_of('/');
    if (slash != std::string::npos) key = key.substr(slash + 1);
    for (const auto &np : kNinePatches) {
        if (key == np.name) return &np;
    }
    return nullptr;
}

const IconAsset *findIconAsset(const std::string &name, int desiredSize) {
    if (name.empty()) return nullptr;
    std::string key = name;
    const size_t slash = key.find_last_of('/');
    if (slash != std::string::npos) key = key.substr(slash + 1);
    if (key.size() > 4 && key.substr(key.size() - 4) == ".svg") {
        key.resize(key.size() - 4);
    }
    const IconAsset *best = nullptr;
    int bestDiff = 1000000;
    for (const auto &ic : kIcons) {
        if (key == ic.name) {
            const int diff = std::abs(ic.size - desiredSize);
            if (diff < bestDiff) { bestDiff = diff; best = &ic; }
        }
    }
    return best;
}

const BitmapFont *findBitmapFont(int desiredSize, bool bold) {
    const BitmapFont *best = nullptr;
    int bestScore = 1000000;
    for (const auto &f : kFonts) {
        int score = std::abs(f.size - desiredSize) * 10 + (f.bold == bold ? 0 : 1);
        if (score < bestScore) { bestScore = score; best = &f; }
    }
    return best;
}

